import{z as n,x as A,o as E,c as B,q as r,j as o,D as a,d as i,s,S as p,b as l}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"薄膜寿命与更换","description":"","frontmatter":{"title":"薄膜寿命与更换","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pellicle-lifetime.md","filePath":"litho/pellicle-lifetime.md","lastUpdated":1791063341000}'),d={name:"litho/pellicle-lifetime.md"};function h(c,e,m,D,T,f){const t=A("Mermaid");return E(),B("div",null,[e[2]||(e[2]=r('<h1 id="薄膜寿命与更换" tabindex="-1">薄膜寿命与更换 <a class="header-anchor" href="#薄膜寿命与更换" aria-label="Permalink to &quot;薄膜寿命与更换&quot;">​</a></h1><div class="epigraph"><p>pellicle 的合同是透过率、皱纹和破膜率随脉冲累积而变。寿命到点必须更换，不是把 DUV 有机膜的年计寿命搬过来。</p><footer>—— 据 ASML 对 EUV pellicle 功率、透过率与更换的公开讨论</footer></div><p><a href="/litho/euv-mask-repair">上一课</a>把版面缺陷修到光化可过。缺口是版上那张膜：<a href="/litho/euv-pellicle">EUV pellicle</a> 已经写过双程 \\(T^2\\) 和热；本课钉寿命与更换节奏。无膜硬跑的风险，留给<a href="/litho/pellicle-free-risk">下一课</a>。不重写 DUV 薄膜安装产线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>修复课假设图形面可接近。装上 pellicle 之后，再修要先揭膜，产尘和破膜风险上升。更日常的是：膜在数百瓦级热流和氢、EUV 下老化——透过率掉、均匀性变、应力致皱、最后破。破膜碎片落在多层上，比从未装膜更糟。功率路线往 500 W、1 kW 走，膜的吸收功率密度先于版本身到达极限。</p><p>缺口是把 pellicle 当消耗品记账：何时换、换的时候机台停多久、透过率漂移如何进剂量。不是再论证「要不要膜」。</p><p><span class="marginnote">「把 pellicle 当消耗品」意思是：它像打印机的墨盒而非终身零件。每一发 EUV 脉冲都在膜上积累微损伤，透过率缓慢下滑、应力逐步累积，到统计点必须主动换新——只是这个「墨盒」的单价与停机成本都高得多。</span></p><p><span class="marginnote">DUV pellicle 更换周期可以很长。EUV 膜的寿命与源功率绑定，必须按层别和 IF 瓦数分层，不能写一张全厂年历。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监测：在线或下机测平均 \\(T\\)、空间指纹、热鼓包干涉图、破洞检测联锁。阈值：剂量补偿加不到、CD 指纹超 SPC、或破膜风险不可接受时更换。物流：膜框与掩模台、机械手兼容，拆装在特定洁净流程，背面颗粒课的接触点约束同样适用。</p><p>CNT 等高透过路线的公开目标是扛更高功率、更长寿命；资格认证仍以扫描机气体与功率为准，不能只用可见光 \\(T\\)。更换时的剂量配方要重标定，因为新膜 \\(T^2\\) 不同。</p><h3 id="透过率漂移要进剂量环-不要只进日历" tabindex="-1">透过率漂移要进剂量环，不要只进日历 <a class="header-anchor" href="#透过率漂移要进剂量环-不要只进日历" aria-label="Permalink to &quot;透过率漂移要进剂量环，不要只进日历&quot;">​</a></h3><p>平均 \\(T\\) 慢降，剂量环可以加扫描时间或源功率。空间指纹和皱纹环补不了，CD 图会先于平均剂量越界。更换判据因此是指纹 SPC，不是「满多少天」。功率爬坡试验必须单独做寿命，250 W 合格不代表下一档 IF 仍合格。</p>',13)),(E(),o(p,null,{default:a(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PWR%5B%22IF%20%E5%8A%9F%E7%8E%87%E4%B8%8E%E6%B0%A2%22%5D%20--%3E%20AGE%5B%22T%20%E4%B8%8B%E9%99%8D%20%2F%20%E8%B5%B7%E7%9A%B1%22%5D%0A%20%20AGE%20--%3E%20DOSE%5B%22%E5%89%82%E9%87%8F%E8%A1%A5%E5%81%BF%22%5D%0A%20%20AGE%20--%3E%20SWAP%5B%22%E6%9B%B4%E6%8D%A2%20pellicle%22%5D%0A%20%20BRK%5B%22%E7%A0%B4%E8%86%9C%22%5D%20--%3E%20LOCK%5B%22%E8%81%94%E9%94%81%E5%81%9C%E6%9C%BA%22%5D%0A%20%20LOCK%20--%3E%20SWAP%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("h2",{id:"机制",tabindex:"-1"},[i("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=l("p",null,"吸收功率加热膜，真空中靠辐射和框导热。温度循环疲劳、氢刻蚀某些成分、EUV 断键，使应力和孔隙率变，\\(T\\) 和相位指纹变成时间函数。OPC 静态层修不了这张时变图。破膜是应力或热点超过强度，碎片尺寸足以打印。联锁必须快过下一场扫描。",-1)),e[5]||(e[5]=l("p",null,[l("span",{class:"marginnote"},"功率翻倍，寿命远不止减半：膜吸收的功率正比于入射强度，老化却常按最热点的损伤累积计——250 W 下刚够用的膜，到 500 W 时热点可能越过损伤门槛，从「缓慢积累」跳到「快速失效」。寿命对功率不是线性，爬坡必须重新做寿命试验。")],-1)),e[6]||(e[6]=l("p",null,[l("span",{class:"marginnote"},"寿命用脉冲数或曝光场数代理，必须声明功率。250 W 下的寿命不能外推到未过滤的 1 kW。")],-1)),(E(),o(p,null,{default:a(()=>[s(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20HEAT%5B%22%E5%90%B8%E6%94%B6%E5%8A%9F%E7%8E%87%E5%8F%91%E7%83%AD%22%5D%20--%3E%20FAT%5B%22%E6%B8%A9%E5%BA%A6%E5%BE%AA%E7%8E%AF%E7%96%B2%E5%8A%B3%22%5D%0A%20%20H2%5B%22%E6%B0%A2%E8%87%AA%E7%94%B1%E5%9F%BA%22%5D%20--%3E%20ETCH%5B%22%E5%88%BB%E8%9A%80%E8%86%9C%E5%86%85%E6%95%8F%E6%84%9F%E6%88%90%E5%88%86%22%5D%0A%20%20EUV%5B%22EUV%20%E5%85%89%E5%AD%90%E6%96%AD%E9%94%AE%22%5D%20--%3E%20CHG%5B%22%E5%8C%96%E5%AD%A6%E7%BB%93%E6%9E%84%E6%94%B9%E5%8F%98%22%5D%0A%20%20FAT%20--%3E%20STRESS%5B%22%E5%BA%94%E5%8A%9B%E4%B8%8E%E5%AD%94%E9%9A%99%E7%8E%87%E5%8F%98%E5%8C%96%22%5D%0A%20%20CHG%20--%3E%20STRESS%0A%20%20ETCH%20--%3E%20STRESS%0A%20%20STRESS%20--%3E%20DROP%5B%22T%20%E4%B8%8B%E9%99%8D%20%2B%20%E8%B5%B7%E7%9A%B1%22%5D%0A%20%20DROP%20--%3E%20BRK%5B%22%E7%A0%B4%E8%86%9C%E9%A3%8E%E9%99%A9%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把「无 pellicle 策略」写成推荐，下一课才写风险。不重写 <a href="/litho/pellicle-mount-inspect">薄膜安装与检验</a> 的 DUV 厂流程。更换是计划停机，破膜是故障停机，稼动账必须分开。出处：ASML EUV pellicle；Bakshi 膜热与透过；pellicle 原理课。</p><p><span class="marginnote">「更换是计划停机，破膜是故障停机」可以类比换轮胎：按里程主动换，进站十几分钟；爆胎了再处理，拖车、误工，还可能连带损伤。破膜碎片落在多层面上更可能让整块掩模报废，所以联锁宁可不必要，不可慢半拍。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV pellicle 是功率相关消耗品，透过率漂移进剂量，破膜是灾难项。</li><li>更换与揭膜修复绑定，要进稼动计划。</li><li>下一课：不装膜时颗粒与产能怎么权衡。</li><li>出处：ASML pellicle 公开材料；Bakshi。</li></ul>',5))])}const C=n(d,[["render",h]]);export{S as __pageData,C as default};
